from datetime import datetime, timedelta
from urllib.parse import parse_qs, urlsplit
import unittest

import calendar_export
import calendar_import
import config
import support


class CalendarExportTests(unittest.TestCase):
    """Verify interoperable calendar text, UTC/offset conversions and marker round trips."""

    def test_uid_and_one_occurrence(self):
        """Export one dated occurrence with a stable UID and no RRULE."""
        event = support.event(is_recurring=True)
        self.assertEqual(calendar_export.make_uid(event), 'weekwise-42-20261102@weekwise')
        text = calendar_export.build_ics(event, now=support.NOW)
        self.assertEqual(text.count('BEGIN:VEVENT'), 1)
        self.assertNotIn('RRULE', text)
        self.assertIn('SEQUENCE:0', text)

    def test_escaping_order(self):
        """Escape literal backslashes before punctuation and newline escapes."""
        self.assertEqual(calendar_export.escape_ics_text('a\\b;c,d\r\ne'), 'a\\\\b\\;c\\,d\\ne')

    def test_utf8_folding(self):
        """Count UTF-8 bytes and the leading continuation space without splitting a character."""
        text = 'SUMMARY:' + 'Zürich 🎓; ' * 35
        folded = calendar_export.fold_ics_line(text)
        for line in folded.split('\r\n'):
            self.assertLessEqual(len(line.encode('utf-8')), 75)
        self.assertEqual(folded.replace('\r\n ', ''), text)

    def test_crlf_and_escaped_multiline_values(self):
        """Avoid bare line feeds and accidental ICS property injection."""
        event = support.event(title='Title\nSTATUS:CANCELLED')
        text = calendar_export.build_ics(event, now=support.NOW)
        self.assertNotIn('\n', text.replace('\r\n', ''))
        self.assertIn('SUMMARY:Title\\nSTATUS:CANCELLED', text)
        self.assertNotIn('\r\nSTATUS:CANCELLED', text)

    def test_winter_and_summer_utc(self):
        """Apply the one-hour winter and two-hour summer Zurich offsets."""
        winter = calendar_export.format_utc(datetime(2026, 11, 5, 18, 30))
        summer = calendar_export.format_utc(datetime(2026, 7, 5, 18, 30))
        self.assertEqual(winter, '20261105T173000Z')
        self.assertEqual(summer, '20260705T163000Z')

    def test_ambiguous_autumn_hour_and_nonexistent_spring_hour(self):
        """Preserve an explicit autumn fold and reject a nonexistent local spring time."""
        first = datetime(2026, 10, 25, 2, 30)
        self.assertEqual(calendar_export.format_utc(first), '20261025T003000Z')
        self.assertEqual(calendar_export.format_utc(first.replace(fold=1)), '20261025T013000Z')
        with self.assertRaises(ValueError):
            calendar_export.format_utc(datetime(2026, 3, 29, 2, 30))

    def test_cancellation_variant(self):
        """Keep the same UID while changing method, sequence and event status."""
        event = support.event()
        text = calendar_export.build_ics(event, cancel=True, now=support.NOW)
        for line in ('METHOD:CANCEL', 'STATUS:CANCELLED', 'SEQUENCE:1'):
            self.assertIn(line, text)
        self.assertIn(calendar_export.make_uid(event), text)
        end = support.NOW.date() + timedelta(days=1)
        blocks, _, recognized = calendar_import.parse_calendar(text, support.NOW.date(), end)
        self.assertEqual(blocks, [])
        self.assertEqual(recognized, set())

    def test_description(self):
        """Limit the original description and retain source, links, estimate note and marker."""
        event = support.event(description='x' * 600, end_is_estimated=True,
                              source_url='https://example.com/event',
                              registration_url='https://example.com/register')
        text = calendar_export.build_description(event)
        self.assertEqual(text.splitlines()[0], 'x' * 500)
        self.assertIn(config.CALENDAR_ESTIMATED_END_NOTE, text)
        self.assertIn('WeekWise ID: weekwise-42-20261102@weekwise', text)

    def test_google_parameters(self):
        """Encode title, UTC times, location and marker without making a network request."""
        event = support.event(title='Zürich & Python')
        query = parse_qs(urlsplit(calendar_export.google_calendar_link(event)).query)
        self.assertEqual(query['text'], [event.title])
        self.assertEqual(query['action'], ['TEMPLATE'])
        self.assertEqual(query['dates'], ['20261102T090000Z/20261102T110000Z'])
        self.assertIn('WeekWise ID:', query['details'][0])

    def test_outlook_offsets(self):
        """Include the correct local UTC offset in Outlook's compose query."""
        for month, offset in [(7, '+02:00'), (11, '+01:00')]:
            event = support.event(start=datetime(2026, month, 5, 18),
                                  end=datetime(2026, month, 5, 20))
            query = parse_qs(urlsplit(calendar_export.outlook_calendar_link(event)).query)
            self.assertTrue(query['startdt'][0].endswith(offset))
            self.assertTrue(query['enddt'][0].endswith(offset))
            self.assertIn(calendar_export.make_uid(event), query['body'][0])

    def test_export_round_trip_known_and_unknown_ids(self):
        """Recognize markers and suppress only occurrences rendered separately from the DB."""
        text = calendar_export.build_ics(support.event(), now=support.NOW)
        start, end = support.NOW.date(), support.NOW.date() + timedelta(days=1)
        blocks, _, ids = calendar_import.parse_calendar(text, start, end, known_event_ids={42})
        self.assertEqual(blocks, [])
        self.assertEqual(ids, {42})
        blocks, _, ids = calendar_import.parse_calendar(text, start, end)
        self.assertEqual(blocks[0].title, config.CALENDAR_UNKNOWN_EVENT_TITLE)
        self.assertEqual(blocks[0].start, support.NOW)
        self.assertEqual(ids, {42})

    def test_invalid_url_cannot_inject_a_property(self):
        """Reject newline-bearing URLs in non-TEXT ICS properties."""
        with self.assertRaises(ValueError):
            event = support.event(source_url='https://example.com/\nSTATUS:CANCELLED')
            calendar_export.build_ics(event)
